var hp := 30
var max_hp := 30
var shield := 0
var hits := 0
var phase := 0.0
var effect := 0.0
var effect_color := Color.WHITE
var effect_text := ""
var defeated := false
var background: Texture2D
var boss_name := ""
const ENEMY_TEXTURE = preload("res://assets/imported/white_erosion.png")
